@dataclass(frozen=True)
class RuleSpec:
    rule_id: str
    observed: str
    catalog: str
    channels: tuple[str, ...]
    cost: float | None

    @property
    def mapping(self) -> str:
        return f"{self.observed}->{self.catalog}"


@dataclass(frozen=True)
class Mutation:
    family: str
    query: str
    rule_id: str
    mapping: str
    channels: tuple[str, ...]
    start: int
    end: int
    replacement: str
    position_stratum: str
    length_bucket: str


@dataclass(frozen=True)
class ComposedMutation:
    family: str
    query: str
    composition_signature: str
    mappings: tuple[str, ...]
    channels: tuple[str, ...]
    position_stratum: str
    length_bucket: str


class Components:
    """Deterministic union-find for leakage-safe query collision components."""

    def __init__(self) -> None:
        self.parent: dict[str, str] = {}

    def add(self, value: str) -> None:
        self.parent.setdefault(value, value)

    def find(self, value: str) -> str:
        self.add(value)
        parent = self.parent[value]
        if parent != value:
            self.parent[value] = self.find(parent)
        return self.parent[value]

    def union(self, first: str, second: str) -> None:
        left = self.find(first)
        right = self.find(second)
        if left == right:
            return
        lower, higher = sorted((left, right))
        self.parent[higher] = lower


def sha256_path(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def stable_hash(*values: object) -> str:
    return hashlib.sha256("|".join(map(str, values)).encode("utf-8")).hexdigest()


def compact(value: object) -> str:
    return re.sub(r"[^A-Z0-9]", "", str(value or "").upper())


def safe_id(value: str) -> str:
    token = re.sub(r"[^A-Z0-9]+", "_", value.upper()).strip("_")
    return token or "EMPTY"


def case_id(prefix: str, *values: object) -> str:
    return f"{prefix}-{stable_hash(SEED, *values)[:16].upper()}"


def length_bucket(value: str) -> str:
    length = len(value)
    if length <= 6:
        return "4-6"
    if length <= 9:
        return "7-9"
    if length <= 12:
        return "10-12"
    if length <= 16:
        return "13-16"
    return "17-24"


def position_stratum(start: int, end: int, total: int) -> str:
    if start == 0:
        return "initial"
    if end == total:
        return "final"
    return "middle"


