def build_rule_specs(algorithm_5: Any, algorithm_2: Any) -> tuple[list[RuleSpec], dict[str, str]]:
    """Collapse duplicate observable mappings while preserving every channel."""

    channels_by_pair: dict[tuple[str, str], set[str]] = defaultdict(set)
    costs_by_pair: dict[tuple[str, str], list[float]] = defaultdict(list)

    def add(observed: str, catalog: str, channel: str, cost: float | None = None) -> None:
        pair = (str(observed), str(catalog))
        if pair[0] == pair[1] or not all(pair):
            return
        channels_by_pair[pair].add(channel)
        if cost is not None:
            costs_by_pair[pair].append(float(cost))

    for observed, catalog, cost in algorithm_5.GRAPHEME_CONFUSION_RULES:
        add(observed, catalog, "direct_grapheme", cost)
    for group in algorithm_5.CONFUSION_GROUPS:
        for observed in sorted(group):
            for catalog in sorted(group):
                if observed != catalog:
                    add(observed, catalog, "weighted_confusion", 0.45)
    for observed, targets in algorithm_5.OCR_DIGIT_TO_LETTERS.items():
        for catalog in sorted(targets):
            add(observed, catalog, "ocr_digit", 0.45)
    for observed, catalog in algorithm_5.LIGATURE_CONFUSION_PAIRS:
        add(observed, catalog, "ligature")
    for observed, catalog in algorithm_5.PHONETIC_REWRITE_PAIRS:
        add(observed, catalog, "phonetic_rewrite")

    specs = []
    for (observed, catalog), channels in sorted(channels_by_pair.items()):
        costs = costs_by_pair.get((observed, catalog), [])
        specs.append(
            RuleSpec(
                rule_id=f"NAME-MAP-{safe_id(observed)}-TO-{safe_id(catalog)}",
                observed=observed,
                catalog=catalog,
                channels=tuple(sorted(channels)),
                cost=min(costs) if costs else None,
            )
        )
    aliases = {
        str(alias): str(target)
        for alias, target in sorted(algorithm_2.ALIAS_TABLE.items())
    }
    return specs, aliases


def build_atomic_candidates(
    family_keys: Sequence[str],
    specs: Sequence[RuleSpec],
) -> tuple[list[Mutation], dict[str, set[str]], dict[str, list[Mutation]]]:
    rows: list[Mutation] = []
    families_by_query: dict[str, set[str]] = defaultdict(set)
    mutations_by_family: dict[str, list[Mutation]] = defaultdict(list)
    for spec in specs:
        for family in family_keys:
            start = 0
            while True:
                index = family.find(spec.catalog, start)
                if index < 0:
                    break
                end = index + len(spec.catalog)
                start = index + 1
                query = family[:index] + spec.observed + family[end:]
                if query == family or not (4 <= len(query) <= 24):
                    continue
                mutation = Mutation(
                    family=family,
                    query=query,
                    rule_id=spec.rule_id,
                    mapping=spec.mapping,
                    channels=spec.channels,
                    start=index,
                    end=end,
                    replacement=spec.observed,
                    position_stratum=position_stratum(index, end, len(family)),
                    length_bucket=length_bucket(query),
                )
                rows.append(mutation)
                families_by_query[query].add(family)
                mutations_by_family[family].append(mutation)
    return rows, families_by_query, mutations_by_family


def generic_substitution(character: str) -> str:
    """Choose a deterministic non-neighbour-looking ordinary substitution."""

    for replacement in "XQZRWVJPKM":
        if replacement != character:
            return replacement
    return "A"


def build_missing_ordinary_candidates(
    family_keys: Sequence[str],
) -> tuple[list[Mutation], dict[str, set[str]]]:
    """Cover ordinary channels absent from the older four-channel benchmark.

    These rows add arbitrary insertion, unrestricted substitution, and
    separator normalization.  They are generated independently of result
    ranks and kept distinct from the medicine-specific OCR registry.
    """

    rows: list[Mutation] = []
    families_by_query: dict[str, set[str]] = defaultdict(set)
    for family in family_keys:
        if not (5 <= len(family) <= 18):
            continue
        positions = tuple(dict.fromkeys((1, len(family) // 2, len(family) - 1)))
        for index in positions:
            inserted = "X" if family[index - 1 : index + 1] != "XX" else "Q"
            query = family[:index] + inserted + family[index:]
            mutation = Mutation(
                family=family,
                query=query,
                rule_id="NAME-ORDINARY-ARBITRARY-INSERTION",
                mapping=f"insert:{inserted}",
                channels=("ordinary_edit",),
                start=index,
                end=index,
                replacement=inserted,
                position_stratum=position_stratum(index, index, len(family)),
                length_bucket=length_bucket(query),
            )
            rows.append(mutation)
            families_by_query[query].add(family)

            replacement = generic_substitution(family[index])
            query = family[:index] + replacement + family[index + 1 :]
            mutation = Mutation(
                family=family,
                query=query,
                rule_id="NAME-ORDINARY-GENERAL-SUBSTITUTION",
                mapping=f"{family[index]}->{replacement}",
                channels=("ordinary_edit",),
                start=index,
                end=index + 1,
                replacement=replacement,
                position_stratum=position_stratum(index, index + 1, len(family)),
                length_bucket=length_bucket(query),
            )
            rows.append(mutation)
            families_by_query[query].add(family)

        split_position = len(family) // 2
        for separator, rule_id in (
            (" ", "NAME-NORMALIZE-WHITESPACE-SEPARATOR"),
            ("-", "NAME-NORMALIZE-PUNCTUATION-SEPARATOR"),
        ):
            query = family[:split_position] + separator + family[split_position:]
            mutation = Mutation(
                family=family,
                query=query,
                rule_id=rule_id,
                mapping=f"insert_separator:{repr(separator)}",
                channels=("normalization",),
                start=split_position,
                end=split_position,
                replacement=separator,
                position_stratum="middle",
                length_bucket=length_bucket(compact(query)),
            )
            rows.append(mutation)
            families_by_query[query].add(family)
    return rows, families_by_query


def operations_query(value: str, operations: Sequence[tuple[int, int, str]]) -> str | None:
    ordered = sorted(operations)
    for index in range(1, len(ordered)):
        if ordered[index][0] < ordered[index - 1][1]:
            return None
    output = value
    for start, end, replacement in reversed(ordered):
        output = output[:start] + replacement + output[end:]
    return output


def ordinary_operations(family: str, blocked: tuple[int, int]) -> dict[str, list[tuple[int, int, str]]]:
    operations: dict[str, list[tuple[int, int, str]]] = defaultdict(list)
    left, right = blocked
    for index, character in enumerate(family):
        if left <= index < right:
            continue
        operations["registered_plus_deletion"].append((index, index + 1, ""))
        operations["registered_plus_duplicate"].append((index, index + 1, character * 2))
        operations["registered_plus_general_substitution"].append(
            (index, index + 1, generic_substitution(character))
        )
        if index + 1 < len(family) and family[index] != family[index + 1]:
            if not (left < index + 2 and index < right):
                operations["registered_plus_transposition"].append(
                    (index, index + 2, family[index + 1] + family[index])
                )
    for index in range(1, len(family)):
        if left < index < right:
            continue
        inserted = "X" if family[index - 1 : index + 1] != "XX" else "Q"
        operations["registered_plus_insertion"].append((index, index, inserted))
        operations["registered_plus_spacing"].append((index, index, " "))
    return operations


def build_two_ordinary_rows(family: str) -> list[ComposedMutation]:
    if not (6 <= len(family) <= 18):
        return []
    first = 1
    second = len(family) - 2
    middle = len(family) // 2
    definitions = (
        (
            "two_ordinary_deletion_transposition",
            ((first, first + 1, ""), (second - 1, second + 1, family[second] + family[second - 1])),
            ("deletion", "transposition"),
        ),
        (
            "two_ordinary_insertion_substitution",
            ((first, first, "X"), (second, second + 1, generic_substitution(family[second]))),
            ("insertion", "general_substitution"),
        ),
        (
            "two_ordinary_duplicate_deletion",
            ((first, first + 1, family[first] * 2), (second, second + 1, "")),
            ("duplicate", "deletion"),
        ),
        (
            "two_ordinary_substitutions",
            (
                (first, first + 1, generic_substitution(family[first])),
                (second, second + 1, generic_substitution(family[second])),
            ),
            ("general_substitution", "general_substitution"),
        ),
        (
            "ordinary_spacing_plus_substitution",
            ((middle, middle, " "), (first, first + 1, generic_substitution(family[first]))),
            ("spacing", "general_substitution"),
        ),
    )
    rows = []
    for signature, operations, mappings in definitions:
        query = operations_query(family, operations)
        if not query or compact(query) == family and signature != "ordinary_spacing_plus_substitution":
            continue
        rows.append(ComposedMutation(
            family=family,
            query=query,
            composition_signature=signature,
            mappings=mappings,
            channels=("ordinary_edit",),
            position_stratum="multiple",
            length_bucket=length_bucket(compact(query)),
        ))
    return rows


def build_composed_candidates(
    family_keys: Sequence[str],
    mutations_by_family: dict[str, list[Mutation]],
) -> tuple[list[ComposedMutation], dict[str, set[str]]]:
    rows: list[ComposedMutation] = []
    families_by_query: dict[str, set[str]] = defaultdict(set)
    for family in family_keys:
        mutations = sorted(
            mutations_by_family.get(family, ()),
            key=lambda item: stable_hash("mutation", item.rule_id, item.start, item.query),
        )[:14]
        if not mutations:
            continue

        pair_count = 0
        for left_index, left in enumerate(mutations):
            for right in mutations[left_index + 1 :]:
                query = operations_query(
                    family,
                    (
                        (left.start, left.end, left.replacement),
                        (right.start, right.end, right.replacement),
                    ),
                )
                if not query or query == family or not (6 <= len(query) <= 24):
                    continue
                signature = (
                    "same_mapping_twice"
                    if left.mapping == right.mapping
                    else "two_registered_mappings"
                )
                channels = tuple(sorted(set(left.channels) | set(right.channels)))
                row = ComposedMutation(
                    family=family,
                    query=query,
                    composition_signature=signature,
                    mappings=tuple(sorted((left.mapping, right.mapping))),
                    channels=channels,
                    position_stratum="multiple",
                    length_bucket=length_bucket(query),
                )
                rows.append(row)
                families_by_query[query].add(family)
                pair_count += 1
                if pair_count >= 12:
                    break
            if pair_count >= 12:
                break

        for mutation in mutations[:3]:
            choices = ordinary_operations(family, (mutation.start, mutation.end))
            for signature, operations in sorted(choices.items()):
                if not operations:
                    continue
                operation = min(
                    operations,
                    key=lambda item: stable_hash(
                        "ordinary", family, mutation.mapping, signature, *item
                    ),
                )
                query = operations_query(
                    family,
                    (
                        (mutation.start, mutation.end, mutation.replacement),
                        operation,
                    ),
                )
                if not query or query == family or not (5 <= len(query) <= 24):
                    continue
                row = ComposedMutation(
                    family=family,
                    query=query,
                    composition_signature=signature,
                    mappings=(mutation.mapping, signature.removeprefix("registered_plus_")),
                    channels=tuple(sorted(set(mutation.channels) | {"ordinary_edit"})),
                    position_stratum=mutation.position_stratum,
                    length_bucket=length_bucket(query),
                )
                rows.append(row)
                families_by_query[query].add(family)
        for row in build_two_ordinary_rows(family):
            rows.append(row)
            families_by_query[row.query].add(family)
    return rows, families_by_query


def build_components(*query_maps: dict[str, set[str]]) -> Components:
    components = Components()
    for query_map in query_maps:
        for families in query_map.values():
            ordered = sorted(families)
            for family in ordered:
                components.add(family)
            for family in ordered[1:]:
                components.union(ordered[0], family)
    return components


def component_members(components: Components) -> dict[str, tuple[str, ...]]:
    groups: dict[str, list[str]] = defaultdict(list)
    for family in components.parent:
        groups[components.find(family)].append(family)
    return {root: tuple(sorted(values)) for root, values in groups.items()}


def split_for_family(components: Components, groups: dict[str, tuple[str, ...]], family: str) -> str:
    root = components.find(family)
    signature = "|".join(groups[root])
    return "holdout" if int(stable_hash(SEED, "split", signature)[:8], 16) % 5 == 0 else "development"


def split_group_id(components: Components, groups: dict[str, tuple[str, ...]], family: str) -> str:
    root = components.find(family)
    return "NAME-GROUP-" + stable_hash(SEED, "group", *groups[root])[:14].upper()


def select_diverse(
    candidates: Sequence[Any],
    quota: int,
    *,
    identity: str,
) -> list[Any]:
    """Prefer unseen position/length cells, then fill deterministically."""

    ordered = sorted(
        candidates,
        key=lambda item: stable_hash(
            identity,
            item.query,
            item.family,
            getattr(item, "rule_id", ""),
            getattr(item, "composition_signature", ""),
        ),
    )
    selected: list[Any] = []
    seen_queries: set[str] = set()
    seen_cells: set[tuple[str, str]] = set()
    for require_new_cell in (True, False):
        for item in ordered:
            if item.query in seen_queries:
                continue
            cell = (item.position_stratum, item.length_bucket)
            if require_new_cell and cell in seen_cells:
                continue
            selected.append(item)
            seen_queries.add(item.query)
            seen_cells.add(cell)
            if len(selected) >= quota:
                return selected
    return selected


def blank_row() -> dict[str, str]:
    return {column: "" for column in COLUMNS}


def make_row(**values: object) -> dict[str, str]:
    row = blank_row()
    for key, value in values.items():
        if key not in row:
            raise KeyError(key)
        if isinstance(value, (list, tuple, set, frozenset)):
            row[key] = ";".join(sorted(str(item) for item in value))
        elif isinstance(value, bool):
            row[key] = "1" if value else "0"
        else:
            row[key] = str(value)
    return row


def build_atomic_rows(
    mutations: Sequence[Mutation],
    aliases: dict[str, str],
    exact_families: set[str],
    query_families: dict[str, set[str]],
    components: Components,
    groups: dict[str, tuple[str, ...]],
) -> tuple[list[dict[str, str]], dict[str, dict[str, int]]]:
    by_rule: dict[str, list[Mutation]] = defaultdict(list)
    for mutation in mutations:
        if mutation.query not in exact_families and query_families[mutation.query] == {mutation.family}:
            by_rule[mutation.rule_id].append(mutation)

    rows: list[dict[str, str]] = []
    coverage: dict[str, dict[str, int]] = {}
    for rule_id, candidates in sorted(by_rule.items()):
        counts: dict[str, int] = {}
        for split, quota in ATOMIC_QUOTAS.items():
            eligible = [
                item
                for item in candidates
                if split_for_family(components, groups, item.family) == split
            ]
            chosen = select_diverse(eligible, quota, identity=f"atomic-{rule_id}-{split}")
            counts[split] = len(chosen)
            for item in chosen:
                rows.append(make_row(
                    case_id=case_id("NAME-ATOMIC", item.rule_id, item.family, item.query),
                    evaluation_kind="accuracy",
                    case_type="atomic_mapping",
                    difficulty_level="L1_atomic",
                    rule_family="name_mapping",
                    rule_id=item.rule_id,
                    mapping=item.mapping,
                    channels=item.channels,
                    operation_count=1,
                    position_stratum=item.position_stratum,
                    length_bucket=item.length_bucket,
                    split=split,
                    split_group_id=split_group_id(components, groups, item.family),
                    query=item.query,
                    source_family_key=item.family,
                    relevant_family_keys=[item.family],
                    maximum_rank=20,
                    match_policy="metric_any_relevant",
                    request_limit=REQUEST_LIMIT,
                    confirmation_required=True,
                    oracle_method="invert one source-declared mapping; require one generated exact-family label globally",
                    generation_method="source registry plus frozen exact catalog; no search outputs",
                ))
        coverage[rule_id] = counts

    for alias, family in sorted(aliases.items()):
        family = compact(family)
        if family not in exact_families:
            continue
        split = split_for_family(components, groups, family)
        rows.append(make_row(
            case_id=case_id("NAME-ALIAS", alias, family),
            evaluation_kind="accuracy",
            case_type="declared_alias",
            difficulty_level="L1_atomic",
            rule_family="medicine_alias",
            rule_id="NAME-DECLARED-ALIAS",
            mapping=f"{alias}->{family}",
            channels=["inherited_alias_table"],
            operation_count=1,
            position_stratum="whole_name",
            length_bucket=length_bucket(alias),
            split=split,
            split_group_id=split_group_id(components, groups, family),
            query=alias,
            source_family_key=family,
            relevant_family_keys=[family],
            maximum_rank=20,
            match_policy="metric_any_relevant",
            request_limit=REQUEST_LIMIT,
            confirmation_required=True,
            oracle_method="literal source alias table",
            generation_method="copy active alias key and exact target before execution",
        ))
    return sorted(rows, key=lambda row: row["case_id"]), coverage


def build_composed_rows(
    candidates: Sequence[ComposedMutation],
    exact_families: set[str],
    query_families: dict[str, set[str]],
    components: Components,
    groups: dict[str, tuple[str, ...]],
) -> list[dict[str, str]]:
    by_signature: dict[str, list[ComposedMutation]] = defaultdict(list)
    for candidate in candidates:
        if candidate.query not in exact_families and query_families[candidate.query] == {candidate.family}:
            by_signature[candidate.composition_signature].append(candidate)
    rows: list[dict[str, str]] = []
    for signature, candidates_for_signature in sorted(by_signature.items()):
        for split, quota in COMPOSED_QUOTAS.items():
            eligible = [
                item
                for item in candidates_for_signature
                if split_for_family(components, groups, item.family) == split
            ]
            chosen = select_diverse(
                eligible,
                quota,
                identity=f"composed-{signature}-{split}",
            )
            for item in chosen:
                rows.append(make_row(
                    case_id=case_id("NAME-COMPOSED", signature, item.family, item.query),
                    evaluation_kind="accuracy",
                    case_type="composed_error",
                    difficulty_level="L2_composed",
                    rule_family="compositional_rescue",
                    rule_id=f"NAME-COMPOSED-{safe_id(signature)}",
                    mapping=item.mappings,
                    channels=item.channels,
                    operation_count=2,
                    composition_signature=signature,
                    position_stratum=item.position_stratum,
                    length_bucket=item.length_bucket,
                    split=split,
                    split_group_id=split_group_id(components, groups, item.family),
                    query=item.query,
                    source_family_key=item.family,
                    relevant_family_keys=[item.family],
                    maximum_rank=20,
                    match_policy="metric_any_relevant",
                    request_limit=REQUEST_LIMIT,
                    confirmation_required=True,
                    oracle_method="compose two nonoverlapping declared transformations on one exact family",
                    generation_method="source registries plus frozen exact catalog; selected before execution",
                ))
    return sorted(rows, key=lambda row: row["case_id"])


def choose_query_rows(
    query_families: dict[str, set[str]],
    *,
    case_type: str,
    quotas: dict[str, int],
    components: Components,
    groups: dict[str, tuple[str, ...]],
) -> list[tuple[str, tuple[str, ...], str]]:
    candidates: dict[str, list[tuple[str, tuple[str, ...]]]] = defaultdict(list)
    for query, families in query_families.items():
        if not (2 <= len(families) <= REQUEST_LIMIT):
            continue
        ordered = tuple(sorted(families))
        split = split_for_family(components, groups, ordered[0])
        candidates[split].append((query, ordered))
    rows: list[tuple[str, tuple[str, ...], str]] = []
    for split, quota in quotas.items():
        ordered = sorted(
            candidates.get(split, ()),
            key=lambda item: stable_hash("safety", case_type, item[0], *item[1]),
        )[:quota]
        rows.extend((query, families, split) for query, families in ordered)
    return rows


def choose_composed_fingerprint_rows(
    families_by_fingerprint: dict[
        tuple[str, str, tuple[str, ...], tuple[str, ...]], set[str]
    ],
    *,
    quotas: dict[str, int],
    components: Components,
    groups: dict[str, tuple[str, ...]],
) -> list[tuple[str, tuple[str, ...], str, str, tuple[str, ...], tuple[str, ...]]]:
    """Select only collisions with identical declared operation evidence.

    A shared output string is not enough to call two families equally
    supported: one family may require a cheap registered pair while another
    needs an unrelated ordinary composition.  The hard ambiguity oracle
    therefore groups by query, composition signature, exact mapping tuple,
    and channel tuple.  Broader query-level collisions remain diagnostics.
    """

    by_split: dict[
        str,
        list[tuple[str, tuple[str, ...], str, tuple[str, ...], tuple[str, ...]]],
    ] = defaultdict(list)
    for (query, signature, mappings, channels), families in families_by_fingerprint.items():
        if not (2 <= len(families) <= REQUEST_LIMIT):
            continue
        ordered = tuple(sorted(families))
        split = split_for_family(components, groups, ordered[0])
        by_split[split].append((query, ordered, signature, mappings, channels))

    rows = []
    for split, quota in quotas.items():
        chosen = sorted(
            by_split.get(split, ()),
            key=lambda item: stable_hash(
                "strict-composed-ambiguity",
                item[0],
                item[2],
                *item[3],
                *item[4],
                *item[1],
            ),
        )[:quota]
        rows.extend(
            (query, families, split, signature, mappings, channels)
            for query, families, signature, mappings, channels in chosen
        )
    return rows


def inverse_registered_frames(
    query: str,
    spec: RuleSpec,
) -> list[tuple[str, tuple[int, int]]]:
    """Reverse one declared mapping and retain its protected catalog span."""

    frames: list[tuple[str, tuple[int, int]]] = []
    start = 0
    while True:
        position = query.find(spec.observed, start)
        if position < 0:
            break
        frame = query[:position] + spec.catalog + query[position + len(spec.observed) :]
        frames.append((frame, (position, position + len(spec.catalog))))
        start = position + 1
    return frames


def position_outside_span(position: int, span: tuple[int, int]) -> bool:
    return position < span[0] or position >= span[1]


def boundary_outside_span(position: int, span: tuple[int, int]) -> bool:
    return position <= span[0] or position >= span[1]


def reverse_one_ordinary_operation(
    frame: str,
    protected_span: tuple[int, int],
    signature: str,
) -> set[str]:
    """Enumerate every exact source string for one declared ordinary error.

    This is an oracle helper, not a search helper.  It independently inverts
    the operation class instead of trusting the generator's sampled witness,
    so a collision label cannot omit an equally supported catalog family.
    """

    sources: set[str] = set()
    if signature == "registered_plus_general_substitution":
        for position, observed in enumerate(frame):
            if not position_outside_span(position, protected_span):
                continue
            for original in "ABCDEFGHIJKLMNOPQRSTUVWXYZ":
                if original != observed and generic_substitution(original) == observed:
                    sources.add(frame[:position] + original + frame[position + 1 :])
    elif signature == "registered_plus_deletion":
        for position in range(len(frame) + 1):
            if not boundary_outside_span(position, protected_span):
                continue
            for original in "ABCDEFGHIJKLMNOPQRSTUVWXYZ":
                sources.add(frame[:position] + original + frame[position:])
    elif signature == "registered_plus_duplicate":
        for position in range(len(frame) - 1):
            if frame[position] != frame[position + 1]:
                continue
            if not (
                position_outside_span(position, protected_span)
                and position_outside_span(position + 1, protected_span)
            ):
                continue
            sources.add(frame[:position] + frame[position + 1 :])
    elif signature == "registered_plus_insertion":
        for position, inserted in enumerate(frame):
            if not position_outside_span(position, protected_span):
                continue
            source = frame[:position] + frame[position + 1 :]
            if not (0 < position < len(source)):
                continue
            expected = "X" if source[position - 1 : position + 1] != "XX" else "Q"
            if inserted == expected:
                sources.add(source)
    elif signature == "registered_plus_spacing":
        sources.add(frame)
    elif signature == "registered_plus_transposition":
        for position in range(len(frame) - 1):
            if frame[position] == frame[position + 1]:
                continue
            if not (
                position_outside_span(position, protected_span)
                and position_outside_span(position + 1, protected_span)
            ):
                continue
            sources.add(
                frame[:position]
                + frame[position + 1]
                + frame[position]
                + frame[position + 2 :]
            )
    return sources


def reverse_two_registered_operations(
    query: str,
    left: RuleSpec,
    right: RuleSpec,
) -> set[str]:
    """Return every exact string formed by reversing two original spans."""

    sources: set[str] = set()
    left_positions = [
        position
        for position in range(len(query) - len(left.observed) + 1)
        if query.startswith(left.observed, position)
    ]
    right_positions = [
        position
        for position in range(len(query) - len(right.observed) + 1)
        if query.startswith(right.observed, position)
    ]
    for left_position in left_positions:
        for right_position in right_positions:
            if left is right and left_position >= right_position:
                continue
            left_span = (left_position, left_position + len(left.observed))
            right_span = (right_position, right_position + len(right.observed))
            if left_span[0] < right_span[1] and right_span[0] < left_span[1]:
                continue
            source = operations_query(
                query,
                (
                    (left_span[0], left_span[1], left.catalog),
                    (right_span[0], right_span[1], right.catalog),
                ),
            )
            if source:
                sources.add(source)
    return sources


def complete_composed_fingerprint_families(
    candidates: Sequence[ComposedMutation],
    specs: Sequence[RuleSpec],
    exact_families: set[str],
) -> dict[tuple[str, str, tuple[str, ...], tuple[str, ...]], set[str]]:
    """Build an independently complete oracle for strict composed collisions."""

    sampled: dict[
        tuple[str, str, tuple[str, ...], tuple[str, ...]], set[str]
    ] = defaultdict(set)
    for candidate in candidates:
        fingerprint = (
            candidate.query,
            candidate.composition_signature,
            candidate.mappings,
            candidate.channels,
        )
        sampled[fingerprint].add(candidate.family)

    specs_by_mapping = {spec.mapping: spec for spec in specs}
    complete: dict[
        tuple[str, str, tuple[str, ...], tuple[str, ...]], set[str]
    ] = {}
    for fingerprint, sampled_families in sampled.items():
        query, signature, mappings, _ = fingerprint
        if len(sampled_families) < 2:
            continue
        compact_query = compact(query)
        oracle_families: set[str] = set()
        if signature.startswith("registered_plus_") and mappings:
            spec = specs_by_mapping.get(mappings[0])
            if spec is not None:
                for frame, protected_span in inverse_registered_frames(compact_query, spec):
                    oracle_families.update(
                        source
                        for source in reverse_one_ordinary_operation(
                            frame,
                            protected_span,
                            signature,
                        )
                        if source in exact_families
                    )
        elif signature in {"same_mapping_twice", "two_registered_mappings"}:
            if len(mappings) == 2:
                left = specs_by_mapping.get(mappings[0])
                right = specs_by_mapping.get(mappings[1])
                if left is not None and right is not None:
                    oracle_families.update(
                        source
                        for source in reverse_two_registered_operations(
                            compact_query,
                            left,
                            right,
                        )
                        if source in exact_families
                    )
        else:
            # The deterministic two-ordinary constructors are already fully
            # defined by their source family; retain every sampled collision.
            oracle_families.update(sampled_families)

        missing_sampled = sampled_families - oracle_families
        if missing_sampled:
            raise RuntimeError(
                "independent composed oracle lost sampled witnesses for "
                f"{fingerprint}: {sorted(missing_sampled)}"
            )
        if 2 <= len(oracle_families) <= REQUEST_LIMIT:
            complete[fingerprint] = oracle_families
    return complete


def build_safety_rows(
    atomic_mutations: Sequence[Mutation],
    composed_mutations: Sequence[ComposedMutation],
    atomic_query_families: dict[str, set[str]],
    composed_query_families: dict[str, set[str]],
    exact_families: set[str],
    components: Components,
    groups: dict[str, tuple[str, ...]],
    strict_composed_families: dict[
        tuple[str, str, tuple[str, ...], tuple[str, ...]], set[str]
    ],
) -> tuple[list[dict[str, str]], list[dict[str, str]]]:
    rows: list[dict[str, str]] = []
    diagnostic_rows: list[dict[str, str]] = []

    for query, families, split in choose_query_rows(
        atomic_query_families,
        case_type="atomic_ambiguity",
        quotas=SAFETY_QUOTAS["atomic_ambiguity"],
        components=components,
        groups=groups,
    ):
        rows.append(make_row(
            case_id=case_id("NAME-SAFETY-AMB", "atomic_ambiguity", query, *families),
            evaluation_kind="safety",
            case_type="atomic_ambiguity",
            difficulty_level="L3_ambiguity",
            rule_family="ambiguity_and_collision",
            rule_id="NAME-ALL-RELEVANT-FAMILIES",
            operation_count=1,
            composition_signature="atomic_ambiguity",
            position_stratum="mixed",
            length_bucket=length_bucket(query),
            split=split,
            split_group_id=split_group_id(components, groups, families[0]),
            query=query,
            relevant_family_keys=families,
            maximum_rank=20,
            match_policy="all_relevant_visible",
            request_limit=REQUEST_LIMIT,
            confirmation_required=True,
            oracle_method="complete one-operation query collision set across source-declared mappings",
            generation_method="collision labels fixed before search; no winner selected from runtime rank",
        ))

    strict_composed = choose_composed_fingerprint_rows(
        strict_composed_families,
        quotas=SAFETY_QUOTAS["composed_same_fingerprint_ambiguity"],
        components=components,
        groups=groups,
    )
    for query, families, split, signature, mappings, channels in strict_composed:
        rows.append(make_row(
            case_id=case_id(
                "NAME-SAFETY-COMPOSED",
                query,
                signature,
                *mappings,
                *channels,
                *families,
            ),
            evaluation_kind="safety",
            case_type="composed_same_fingerprint_ambiguity",
            difficulty_level="L3_ambiguity",
            rule_family="ambiguity_and_collision",
            rule_id="NAME-SAME-FINGERPRINT-ALL-FAMILIES",
            mapping=mappings,
            channels=channels,
            operation_count=2,
            composition_signature=signature,
            position_stratum="mixed",
            length_bucket=length_bucket(query),
            split=split,
            split_group_id=split_group_id(components, groups, families[0]),
            query=query,
            relevant_family_keys=families,
            maximum_rank=20,
            match_policy="all_relevant_visible",
            request_limit=REQUEST_LIMIT,
            confirmation_required=True,
            oracle_method="complete collision set for one identical two-operation fingerprint",
            generation_method="query, composition, mappings, and channels fixed before search",
        ))

    # Preserve the broader query-level collision cohort as a diagnostic.  A
    # family reached through a different two-operation path is not necessarily
    # equally supported, so missing one lowers diagnostic recall but is not a
    # hard ambiguity violation.
    for query, families, split in choose_query_rows(
        composed_query_families,
        case_type="composed_ambiguity",
        quotas=DIAGNOSTIC_QUOTAS["cross_rule_composed_collision"],
        components=components,
        groups=groups,
    ):
        diagnostic_rows.append(make_row(
            case_id=case_id("NAME-DIAGNOSTIC-CROSS-RULE", query, *families),
            evaluation_kind="diagnostic",
            case_type="cross_rule_composed_collision",
            difficulty_level="L3_cross_rule_diagnostic",
            rule_family="cross_rule_collision_breadth",
            rule_id="NAME-CROSS-RULE-COLLISION-DIAGNOSTIC",
            operation_count=2,
            composition_signature="mixed_two_operation_paths",
            position_stratum="mixed",
            length_bucket=length_bucket(query),
            split=split,
            split_group_id=split_group_id(components, groups, families[0]),
            query=query,
            relevant_family_keys=families,
            maximum_rank=20,
            match_policy="diagnostic_all_relevant",
            request_limit=REQUEST_LIMIT,
            confirmation_required=True,
            oracle_method="complete query-level collision set across unlike two-operation paths",
            generation_method="preserved breadth diagnostic; missing labels do not imply equal-evidence safety failure",
        ))

    exact_collision_candidates: dict[str, set[str]] = defaultdict(set)
    for mutation in atomic_mutations:
        if mutation.query in exact_families and mutation.query != mutation.family:
            exact_collision_candidates[mutation.query].add(mutation.family)
    by_split: dict[str, list[tuple[str, tuple[str, ...]]]] = defaultdict(list)
    for literal, alternatives in exact_collision_candidates.items():
        split = split_for_family(components, groups, literal)
        by_split[split].append((literal, tuple(sorted(alternatives))))
    for split, quota in SAFETY_QUOTAS["exact_name_collision"].items():
        chosen = sorted(
            by_split.get(split, ()),
            key=lambda item: stable_hash("exact-collision", item[0], *item[1]),
        )[:quota]
        for literal, alternatives in chosen:
            rows.append(make_row(
                case_id=case_id("NAME-SAFETY-EXACT", literal, *alternatives),
                evaluation_kind="safety",
                case_type="exact_name_collision",
                difficulty_level="L3_ambiguity",
                rule_family="literal_exact_protection",
                rule_id="NAME-EXACT-RANK1-GUARD",
                operation_count=0,
                position_stratum="whole_name",
                length_bucket=length_bucket(literal),
                split=split,
                split_group_id=split_group_id(components, groups, literal),
                query=literal,
                source_family_key=literal,
                relevant_family_keys=[literal],
                expected_rank=1,
                maximum_rank=1,
                match_policy="literal_exact_rank1",
                request_limit=REQUEST_LIMIT,
                confirmation_required=True,
                oracle_method="literal exact catalog key",
                generation_method="retain exact query that is also reachable from another family by a declared mapping",
                notes=f"confusion_reachable_alternatives={';'.join(alternatives)}",
            ))
    return (
        sorted(rows, key=lambda row: row["case_id"]),
        sorted(diagnostic_rows, key=lambda row: row["case_id"]),
    )


def build_boundary_rows() -> list[dict[str, str]]:
    rows: list[dict[str, str]] = []
    for length, expected in ((3, 0), (4, 1), (5, 1), (6, 2), (24, 2), (25, 0)):
        query = "E" + "A" * (length - 1)
        rows.append(make_row(
            case_id=case_id("NAME-BOUNDARY-LENGTH", length),
            evaluation_kind="source_contract",
            case_type="grapheme_depth_boundary",
            difficulty_level="L4_source_boundary",
            rule_family="bounded_direct_rewrite",
            rule_id="NAME-MAX-GRAPHEME-CONFUSIONS",
            operation_count=expected,
            position_stratum="initial",
            length_bucket=str(length),
            split="source_contract",
            split_group_id="SOURCE-BOUNDARY",
            query=query,
            expected_source_contract="maximum_grapheme_confusions",
            expected_source_value=expected,
            oracle_method="literal source constant boundary",
            generation_method="synthetic length probe",
        ))
    rows.extend((
        make_row(
            case_id="NAME-BOUNDARY-NONTRANS-I-E-G",
            evaluation_kind="source_contract",
            case_type="non_transitivity",
            difficulty_level="L4_source_boundary",
            rule_family="original_span_consumption",
            rule_id="NAME-NONTRANSITIVE-I-E-G",
            operation_count=2,
            split="source_contract",
            split_group_id="SOURCE-BOUNDARY",
            query="IARDX",
            expected_source_contract="variant_absent",
            forbidden_source_value="GARDX",
            oracle_method="I->E and E->G may not rewrite one original character twice",
            generation_method="synthetic overlap-chain probe",
        ),
        make_row(
            case_id="NAME-BOUNDARY-FIRST-CHAR-PAIRWISE",
            evaluation_kind="source_contract",
            case_type="first_character_scope",
            difficulty_level="L4_source_boundary",
            rule_family="bounded_first_character_retrieval",
            rule_id="NAME-FIRST-CHAR-E-G-ONLY",
            operation_count=1,
            split="source_contract",
            split_group_id="SOURCE-BOUNDARY",
            query="EYLEA",
            expected_source_contract="first_char_variants_exact",
            expected_source_value="GYLEA",
            oracle_method="pairwise registry only; grouped CKQ/SZ/etc remain scoring evidence",
            generation_method="source-function probe",
        ),
        make_row(
            case_id="NAME-BOUNDARY-FIRST-CHAR-NO-CKQ-EXPANSION",
            evaluation_kind="source_contract",
            case_type="first_character_scope",
            difficulty_level="L4_source_boundary",
            rule_family="bounded_first_character_retrieval",
            rule_id="NAME-FIRST-CHAR-NO-GROUP-EXPANSION",
            operation_count=0,
            split="source_contract",
            split_group_id="SOURCE-BOUNDARY",
            query="CANDY",
            expected_source_contract="first_char_variants_exact",
            expected_source_value="",
            oracle_method="legacy confusion groups do not expand first-character candidate pools",
            generation_method="source-function probe",
        ),
        make_row(
            case_id="NAME-BOUNDARY-VARIANT-CAP",
            evaluation_kind="source_contract",
            case_type="variant_cap",
            difficulty_level="L4_source_boundary",
            rule_family="bounded_direct_rewrite",
            rule_id="NAME-GRAPHEME-VARIANT-CAP",
            operation_count=2,
            split="source_contract",
            split_group_id="SOURCE-BOUNDARY",
            query="IEYG" * 6,
            expected_source_contract="variant_count_at_most",
            expected_source_value=512,
            oracle_method="GRAPHEME_VARIANT_LIMIT source constant",
            generation_method="24-character confusion-heavy probe",
        ),
        make_row(
            case_id="NAME-BOUNDARY-DETERMINISTIC-ORDER",
            evaluation_kind="source_contract",
            case_type="determinism",
            difficulty_level="L4_source_boundary",
            rule_family="bounded_direct_rewrite",
            rule_id="NAME-GRAPHEME-DETERMINISM",
            operation_count=2,
            split="source_contract",
            split_group_id="SOURCE-BOUNDARY",
            query="OMGPRAZOLG",
            expected_source_contract="variants_repeat_exactly",
            oracle_method="two calls must return byte-for-byte equal ordered tuples",
            generation_method="source-function repeat probe",
        ),
    ))
    return sorted(rows, key=lambda row: row["case_id"])


def write_csv(path: Path, rows: Sequence[dict[str, str]]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("w", encoding="utf-8", newline="") as handle:
        writer = csv.DictWriter(handle, fieldnames=COLUMNS, extrasaction="raise")
        writer.writeheader()
        writer.writerows(rows)


def main() -> None:
    provenance = collect_provenance(REPO)
    if sha256_path(CATALOG_PATH) != CATALOG_SHA256:
        raise RuntimeError("catalog hash differs from the locked benchmark catalog")
    algorithm_6 = load_algorithm6()
    catalog = algorithm_6.prepare_catalog()
    algorithm_5 = catalog.algorithm_5_module
    algorithm_2 = catalog.algorithm_5_catalog.external_module
    exact_families = {
        family.compact
        for family in catalog.algorithm_5_catalog.rescue_index.families
    }
    if len(exact_families) != 17_476:
        raise RuntimeError(f"expected 17,476 families, found {len(exact_families)}")
    family_keys = sorted(
        family
        for family in exact_families
        if family.isalpha() and 4 <= len(family) <= 20
    )

    specs, aliases = build_rule_specs(algorithm_5, algorithm_2)
    atomic_candidates, atomic_query_families, mutations_by_family = build_atomic_candidates(
        family_keys,
        specs,
    )
    ordinary_candidates, ordinary_query_families = build_missing_ordinary_candidates(
        family_keys,
    )
    atomic_candidates.extend(ordinary_candidates)
    for query, families in ordinary_query_families.items():
        atomic_query_families[query].update(families)
    composed_candidates, composed_query_families = build_composed_candidates(
        family_keys,
        mutations_by_family,
    )
    strict_composed_families = complete_composed_fingerprint_families(
        composed_candidates,
        specs,
        exact_families,
    )
    strict_composed_query_families: dict[str, set[str]] = defaultdict(set)
    for (query, _, _, _), families in strict_composed_families.items():
        strict_composed_query_families[query].update(families)
    components = build_components(
        atomic_query_families,
        composed_query_families,
        strict_composed_query_families,
    )
    for family in exact_families:
        components.add(family)
    groups = component_members(components)

    atomic_rows, rule_coverage = build_atomic_rows(
        atomic_candidates,
        aliases,
        exact_families,
        atomic_query_families,
        components,
        groups,
    )
    composed_rows = build_composed_rows(
        composed_candidates,
        exact_families,
        composed_query_families,
        components,
        groups,
    )
    safety_rows, diagnostic_rows = build_safety_rows(
        atomic_candidates,
        composed_candidates,
        atomic_query_families,
        composed_query_families,
        exact_families,
        components,
        groups,
        strict_composed_families,
    )
    boundary_rows = build_boundary_rows()
    outputs = {
        "atomic": atomic_rows,
        "composed": composed_rows,
        "safety": safety_rows,
        "diagnostic": diagnostic_rows,
        "boundary": boundary_rows,
    }
    file_records = []
    for name, rows in outputs.items():
        path = FILES[name]
        write_csv(path, rows)
        file_records.append({
            "name": name,
            "path": str(path.relative_to(REPO)),
            "rows": len(rows),
            "sha256": sha256_path(path),
            "bytes": path.stat().st_size,
        })

    manifest = {
        "schema_version": 2,
        "generated_at_utc": datetime.now(timezone.utc).isoformat(),
        "generator": str(Path(__file__).relative_to(REPO)),
        "generator_sha256": sha256_path(Path(__file__)),
        "seed": SEED,
        "source_provenance": provenance,
        "catalog": {
            "path": str(CATALOG_PATH.relative_to(REPO)),
            "sha256": sha256_path(CATALOG_PATH),
            "families": len(exact_families),
            "eligible_alpha_families": len(family_keys),
        },
        "protocol": {
            "search_output_used_for_generation": False,
            "split_policy": "connected components over every generated query-to-family collision; SHA-256 component assignment",
            "atomic_quota_per_mapping": ATOMIC_QUOTAS,
            "composed_quota_per_signature": COMPOSED_QUOTAS,
            "safety_quotas": SAFETY_QUOTAS,
            "diagnostic_quotas": DIAGNOSTIC_QUOTAS,
            "public_result_limit": REQUEST_LIMIT,
            "accuracy_rows_are_metrics_not_green-regression assertions": True,
            "safety_rows_are_release_gates": True,
            "cross_rule_collision_rows_are_diagnostics_not_release_gates": True,
        },
        "rule_inventory": {
            "observable_mapping_count": len(specs),
            "declared_alias_count": len(aliases),
            "mappings": [asdict(spec) for spec in specs],
            "atomic_selected_by_rule_and_split": rule_coverage,
        },
        "candidate_universes": {
            "atomic_candidates": len(atomic_candidates),
            "missing_ordinary_channel_candidates": len(ordinary_candidates),
            "atomic_distinct_queries": len(atomic_query_families),
            "composed_candidates": len(composed_candidates),
            "composed_distinct_queries": len(composed_query_families),
            "strict_composed_collision_fingerprints": len(strict_composed_families),
            "collision_components": len(groups),
        },
        "files": file_records,
    }
    MANIFEST_PATH.parent.mkdir(parents=True, exist_ok=True)
    MANIFEST_PATH.write_text(
        json.dumps(manifest, indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )
    print(json.dumps({
        "files": file_records,
        "manifest": str(MANIFEST_PATH.relative_to(REPO)),
        "manifest_sha256": sha256_path(MANIFEST_PATH),
    }, indent=2))


if __name__ == "__main__":
    main()
